update public.government_schemes
set source_url='https://www.bisp.gov.pk/Detail/YTgzNjkxM2YtN2ViMC00MjA5LWI0MDMtNzM4ZWJmMGVlNzc5',
source_document_url='https://www.bisp.gov.pk/Detail/NDhkMmM4MDUtYjQ3Ni00YjI4LWJkZWQtZTcyODBmYzYzYTk3',
benefit_details='Eligible beneficiary households may receive cash assistance through the Benazir Kafaalat programme. The BISP programme page reviewed contains older stipend / eligibility figures that are not clearly dated for the current payment cycle; this listing therefore does not repeat a payment amount or PMT threshold. Confirm the current quarter’s official notification and your household status through BISP.',
eligibility_text='Eligibility is determined by BISP through its official registry and assessment process. Older figures on the programme page are not treated as current eligibility rules in this listing. A status check does not guarantee enrolment or payment. Use only BISP’s official 8171 service and follow instructions from an official BISP Tehsil Office.',
application_steps='Check your status only through https://8171.pass.gov.pk or the official 8171 SMS service. If BISP directs you to update or complete a survey, visit the relevant official BISP Tehsil registration desk. BISP states that survey/registration is free and messages from numbers other than 8171 are fraudulent. Never pay an agent.',
fees_and_repayment='BISP states that survey / registration is free and 8171 is its only official SMS number. Do not pay registration agents, trust other SMS numbers or rely on old stipend amounts / PMT thresholds without a current official notice.',
verified_at=now(),next_review_at=now()+interval '7 days',updated_at=now()
where slug='benazir-kafaalat-programme';

update public.government_schemes
set source_document_url='https://radio.gov.pk/08-11-2026/pm-increases-youth-agriculture-loan-limit-to-rs25m',
benefit_details='The official PMYB&ALS portal currently displays three tiers: up to PKR 500,000 at 0% markup; above PKR 500,000 up to PKR 1.5 million at 5%; and above PKR 1.5 million up to PKR 7.5 million at 7%. Radio Pakistan reported the Government’s 8 November 2026 announcement raising the maximum loan limit to PKR 25 million and lowering the minimum age to 18. The information portal reviewed still shows the older three tiers, so the detailed Tier 4 markup, tenor and live application process are not treated as confirmed by the portal. This is repayable financing, not a grant.',
eligibility_text='The PMYB&ALS information portal currently lists Pakistani residents aged 21–45 with entrepreneurial potential, with an 18-year lower age limit for IT / e-commerce businesses. Radio Pakistan reported an 8 November 2026 Government announcement lowering the minimum age to 18 for the scheme; the portal page reviewed has not yet reflected this change. Check the PMYP Digital Youth Hub and participating bank for the currently implemented age and eligibility rules. Government employees and non-residents should review official exclusions.',
application_steps='The Government announcement reported by Radio Pakistan on 8 November 2026 directs applicants to the Prime Minister’s Digital Youth Hub at pmyp.gov.pk or the PMYP mobile app. The separate PMYB&ALS information portal reviewed still displays the original three tiers and old eligibility wording; confirm the live form route and implementation of the increased limit through the official hub / participating bank before applying. No agent or recommendation is required; banks decide applications on merit. Never upload identity or supporting documents to Hello Sadiqabad or share them in chat.',
fees_and_repayment='The portal currently lists 0% markup up to PKR 500,000; 5% above PKR 500,000 up to PKR 1.5 million; and 7% above PKR 1.5 million up to PKR 7.5 million. The Government announcement raises the maximum loan limit to PKR 25 million, but the portal page reviewed does not yet publish the new Tier 4 markup / tenor. Confirm all repayment, security and fee terms in the current official form and with the participating bank.',
official_apply_url='https://pmyp.gov.pk/',
verified_at=now(),next_review_at=now()+interval '7 days',updated_at=now()
where slug='prime-minister-youth-business-agriculture-loan';